t.script:
// Ajustar cada numero a la caja girada: ancho = 148 mm (largo de la etiqueta), alto = 98 mm.
var MM = 96 / 25.4;
var ANCHO = 144 * MM, ALTO = 94 * MM, ESTIRAR_MAX = 1.8;
var kts = document.getElementsByClassName('koroshi-k');
for (var i = 0; kts.length > i; i++) {
    var el = kts[i];
    var fs = 200;
    el.style.fontSize = fs + 'pt';
    var w = el.offsetWidth;
    fs = fs * ANCHO / w;
    el.style.fontSize = fs + 'pt';
    // Altura de las letras (mayusculas y numeros) ~ 0,72 del tamano de letra
    var alto_letra = 0.72 * fs * 96 / 72;
    var sy = Math.min(ESTIRAR_MAX, Math.max(1, ALTO / alto_letra));
    el.style.webkitTransform = 'scale(1, ' + sy + ')';
    el.style.transform = 'scale(1, ' + sy + ')';
}
